using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace Stackshot
{
    internal static class DailyWorkflowTests
    {
        static Bitmap White(int width,int height){var image=new Bitmap(width,height);using(var g=Graphics.FromImage(image))g.Clear(Color.White);return image;}
        internal static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("daily pins/rotate and flip preserve editable source and isolate neighboring pins",delegate{
                var image=White(100,60);image.SetPixel(0,0,Color.Red);image.SetPixel(99,59,Color.Blue);
                using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(image),new Rectangle(0,0,1200,900)))using(var neighbor=PinWindow.CreateHidden(AnnotationDocument.FromImage(White(100,60)),new Rectangle(0,0,1200,900))){
                    pin.ChangeView(1,false,false);using(var result=pin.ViewImage()){check(result.Size==new Size(60,100),"rotated size");check(result.GetPixel(59,0).R==255&&result.GetPixel(59,0).B==0,"orientation");result.Save(Path.Combine(output,"pin-rotated-view.png"));}
                    pin.ChangeView(3,true,false);using(var result=pin.ViewImage())check(result.GetPixel(99,0).R==255&&result.GetPixel(99,0).B==0,"horizontal flip");
                    using(var original=pin.ExportDocument())check(original.Source.Size==new Size(100,60)&&original.Source.GetPixel(0,0).ToArgb()==Color.Red.ToArgb(),"source was flattened");
                    using(var edit=pin.ExportDocument())pin.ReplaceDocument(edit.Clone());using(var result=pin.ViewImage())check(result.GetPixel(99,0).ToArgb()==Color.Red.ToArgb(),"edit reset view");
                    check(neighbor.State.QuarterTurns==0&&!neighbor.State.FlipX,"view leaked");pin.ChangeView(0,false,false,true);using(var reset=pin.ViewImage())check(reset.Size==new Size(100,60)&&reset.GetPixel(0,0).ToArgb()==Color.Red.ToArgb(),"reset");check(!pin.Visible&&!neighbor.Visible,"desktop shown");
                }
            });
            run("daily pins/view state roundtrip includes direction and explicit hidden status",delegate{var state=new PinState{Bounds=new Rectangle(-900,40,300,200),QuarterTurns=3,FlipX=true,FlipY=true,HiddenByUser=true};var read=PinState.FromJson(state.ToJson());check(read.QuarterTurns==3&&read.FlipX&&read.FlipY&&read.HiddenByUser&&read.Bounds==state.Bounds,"state roundtrip");});
            run("daily pins/hide and restore uses only marked pins and safe adapter",delegate{
                using(var a=PinWindow.CreateHidden(AnnotationDocument.FromImage(White(100,60)),new Rectangle(0,0,1200,900)))using(var b=PinWindow.CreateHidden(AnnotationDocument.FromImage(White(100,60)),new Rectangle(0,0,1200,900))){a.SetPinHidden(true);int shown=0;PinWindow.RestoreAllPins(delegate(PinWindow pin){check(pin==a,"restored already hidden window");shown++;});check(shown==1&&!a.State.HiddenByUser&&!b.Visible&&!a.Visible,"restored wrong set or used desktop");PinWindow.RestoreAllPins(delegate{shown++;});check(shown==1,"restore is not idempotent");}
            });
            run("daily pins/snap uses image edges negative monitors and adjacency only",delegate{var area=new Rectangle(-1200,0,1200,900);var r=PinViews.Snap(new Rectangle(-1216,80,248,148),new Rectangle[0],area,24,10);check(r.Left==-1224,"screen image edge");var other=new Rectangle(-800,100,248,148);r=PinViews.Snap(new Rectangle(-600,104,248,148),new[]{other},area,24,10);check(r.Top==100,"edge align");var far=new Rectangle(-500,600,248,148);check(PinViews.Snap(far,new[]{other},area,24,10)==far,"snapped unrelated distant window");});
            run("daily pins/wheel preferences and rotation keys use production handlers",delegate{
                using(var p=PinWindow.CreateHidden(AnnotationDocument.FromImage(White(240,140)),new Rectangle(0,0,1920,1080))){p.ApplyPinAppearance(new Preferences{PinWheelOpacity=true,PinReverseWheel=true});p.SetOpacityPercent(80);p.ApplyPinWheel(120,Point.Empty,Keys.None);check(p.State.OpacityPercent==75,"swapped reversed wheel");float z=p.State.Zoom;p.ApplyPinWheel(-120,Point.Empty,Keys.Control);check(p.State.Zoom>z,"ctrl zoom");check(p.ApplyPinKey(Keys.Control|Keys.R)&&p.State.QuarterTurns==1,"rotation key");check(p.ApplyPinKey(Keys.Control|Keys.H)&&p.State.FlipX,"flip key");var menu=p.ContextMenuStrip.Items.OfType<ToolStripMenuItem>().First(i=>i.Text=="旋转与翻转");menu.DropDownItems[4].PerformClick();check(p.State.QuarterTurns==0&&!p.State.FlipX,"reset menu callback");}
            });
            run("daily preferences/import validates without carrying machine startup consent",delegate{
                var folder=Path.Combine(output,"daily-settings");Directory.CreateDirectory(folder);var path=Path.Combine(folder,"preferences.json");var p=new Preferences{FullScreen="Ctrl+Alt+F",InitialTool="Callout",PinOpacity=65,PinReverseWheel=true,RunOnStartup=true};PreferenceTransfer.Export(p,path);var read=PreferenceTransfer.Import(path,false);check(!read.RunOnStartup&&read.PinOpacity==65&&read.InitialTool=="Callout"&&read.FullScreen==p.FullScreen,"portable preferences");check(p.RunOnStartup,"export mutated live consent");read=PreferenceTransfer.Import(path,true);check(read.RunOnStartup,"import changed current consent");File.WriteAllText(path,"{\"Version\":1,\"PinOpacity\":2}");bool rejected=false;try{PreferenceTransfer.Import(path,false);}catch(InvalidDataException){rejected=true;}check(rejected,"invalid import accepted");
            });
            run("daily capture/explicit workflow ranges preserve physical negative coordinates and reject stale monitors",delegate{var desktop=new Rectangle(-1600,0,3520,1080);var monitor=new Rectangle(-1600,0,1600,900);var window=new Rectangle(-1400,60,700,480);check(CaptureWorkflows.Resolve("fullscreen",desktop,monitor,window,null)==monitor,"full screen");check(CaptureWorkflows.Resolve("window",desktop,monitor,window,null)==window,"current window");check(CaptureWorkflows.Resolve("repeat",desktop,monitor,window,new[]{-1300,50,400,300})==new Rectangle(-1300,50,400,300),"repeat");check(CaptureWorkflows.Resolve("repeat",new Rectangle(0,0,1920,1080),monitor,window,new[]{-1300,50,400,300}).IsEmpty,"stale range was silently shifted");});
            run("daily capture/default annotation tool and cursor preference persist and drive actual overlay",delegate{var settings=new Preferences{InitialTool="Callout",IncludeCursor=true};using(var overlay=new CaptureOverlay(White(900,650),new Rectangle(-900,0,900,650),new Rectangle(-800,80,500,300),new[]{new Rectangle(-900,0,900,650)},null,70,settings)){check(overlay.AnnotationCanvas.Tool==Tool.Callout,"default tool ignored");check(!overlay.Completed&&overlay.ScreenSelection==new Rectangle(-800,80,500,300),"initial selection");}var store=new PreferenceStore(Path.Combine(output,"daily-capture-preferences"));store.Save(settings);var read=store.Load();check(read.IncludeCursor&&read.InitialTool=="Callout","preferences not persisted");});
            run("daily completion/default writes nothing and three modes dispatch correct clipboard and file effects",delegate{
                string root=Path.Combine(output,"completion-"+Guid.NewGuid().ToString("N"));int copies=0;using(var image=White(90,60)){
                    var p=new Preferences();check(CaptureCompletion.Deliver(image,p,root,delegate{copies++;})==null&&copies==1&&!Directory.Exists(root),"default persisted pixels");
                    p.SaveDirectory="Captures";p.CompleteAction="copy-save";p.FileNameTemplate="建筑-{date}-{id}";var first=CaptureCompletion.Deliver(image,p,root,delegate{copies++;});check(File.Exists(first)&&copies==2,"copy-save");
                    p.CompleteAction="save";var second=CaptureCompletion.Deliver(image,p,root,delegate{copies++;});check(File.Exists(second)&&first!=second&&copies==2,"save-only copied");
                    CaptureCompletion.Deliver(image,p,root,delegate{copies++;},false);check(copies==3,"copy and continue obeyed save-only preference");
                    p.SaveDirectory="History";bool rejected=false;try{CaptureCompletion.SaveDirectory(p,root);}catch(IOException){rejected=true;}check(rejected,"history and chosen save directory overlap");
                }
            });
            run("daily history/explicit opt-in retention limit and clear preserve manually saved images",delegate{
                string root=Path.Combine(output,"history-"+Guid.NewGuid().ToString("N"));var store=new CaptureHistory(root);using(var image=White(70,40)){for(int i=0;i<12;i++)store.Record(image,10);check(store.List().Length==10&&Directory.GetFiles(store.Folder,"*.png").Length==10,"history prune");var item=store.List()[0];store.Delete(item.Id);check(store.List().Length==9&&!File.Exists(store.ImagePath(item.Id)),"delete");File.WriteAllText(Path.Combine(store.Folder,"manual.png"),"user image");Directory.CreateDirectory(Path.Combine(root,"Captures"));File.WriteAllText(Path.Combine(root,"Captures","saved.png"),"user image");store.Clear();check(store.List().Length==0&&File.Exists(Path.Combine(store.Folder,"manual.png"))&&File.Exists(Path.Combine(root,"Captures","saved.png")),"clear deleted user image");}
            });
            run("daily history/corrupt path IDs cannot traverse outside owned cache",delegate{string root=Path.Combine(output,"history-invalid-"+Guid.NewGuid().ToString("N"));var store=new CaptureHistory(root);Directory.CreateDirectory(store.Folder);File.WriteAllText(Path.Combine(store.Folder,"index.json"),"[{\"Id\":\"../outside\",\"Width\":10,\"Height\":10}]");bool rejected=false;try{store.List();}catch(InvalidDataException){rejected=true;}check(rejected,"untrusted path accepted");rejected=false;try{store.ImagePath("../outside");}catch(ArgumentException){rejected=true;}check(rejected,"ImagePath traversal");});
            run("daily installer/cleanup removes only matching installed startup and owned cache",delegate{var entry=new FakeStartup();string executable=Path.Combine(output,"App","ScreenCraft.exe");entry.Value=StartupCommand.For(executable);InstallerCleanup.RemoveOwnedStartup(entry,executable);check(entry.Value==null&&entry.Removed==1,"own startup not removed");entry.Value=StartupCommand.For(Path.Combine(output,"Portable","ScreenCraft.exe"));InstallerCleanup.RemoveOwnedStartup(entry,executable);check(entry.Value!=null&&entry.Removed==1,"portable startup removed");});
            run("daily settings/seven styled pages save pin export workflow preferences through production controls",delegate{
                Preferences saved=null;using(var settings=new SettingsDialog(new Preferences(),output,delegate(Preferences p){saved=p;return null;})){
                    var initial=(PreferencesChoice)Find(settings,"默认标注工具");initial.SelectedIndex=6;((NumericUpDown)Find(settings,"新贴图透明度")).Value=65;((PreferencesSwitch)Find(settings,"反向缩放滚轮")).Checked=true;((PreferencesChoice)Find(settings,"完成后动作")).SelectedIndex=1;((TextBox)Find(settings,"保存文件名模板")).Text="建筑-{date}-{id}";((PreferencesSwitch)Find(settings,"保留截图历史")).Checked=true;
                    foreach(var page in new[]{1,6})using(var image=settings.RenderSyntheticPreview(page))image.Save(Path.Combine(output,"daily-settings-"+page+"-offscreen.png"));
                    settings.SelectPage(6);foreach(Control control in settings.Controls)if(control is PreferencesButton&&control.Text=="保存并应用")typeof(Button).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(control,new object[]{EventArgs.Empty});
                    check(saved!=null&&saved.InitialTool=="Callout"&&saved.PinOpacity==65&&saved.PinReverseWheel&&saved.CompleteAction=="copy-save"&&saved.HistoryEnabled,"settings controls lost");check(saved.Hotkeys().Count==10,"new hotkey actions absent");check(!settings.Visible,"settings shown");
                }
            });
            run("daily background/solid gradient frame ratio undo and editable project preserve source pixels",delegate{
                using(var canvas=new Canvas(White(240,160))){canvas.AddAnnotation(ScreenCraftTests.Mark(Tool.Arrow,30,35,190,100));canvas.ApplyBackground(true,new Settings{BgKind=1,BgColor=0xD3E4F3,BgPadding=70,BgRadius=80,BgShadow=true,BgRatio="16:9",BgAlign=4});using(var image=canvas.Render()){check(image.Width>240&&image.Height>160&&Math.Abs(image.Width/(double)image.Height-16.0/9)<.02,"background size/ratio");check(image.GetPixel(0,0).ToArgb()==Color.FromArgb(211,228,243).ToArgb(),"solid background "+image.GetPixel(0,0));image.Save(Path.Combine(output,"daily-background-solid.png"));}canvas.Undo();check(!canvas.BgOn&&canvas.AnnotationCount==1,"background undo removed annotations");canvas.Redo();check(canvas.BgOn,"redo");var path=Path.Combine(output,"background-editable.sccraft");using(var document=canvas.ExportDocument())document.Save(path);using(var document=AnnotationDocument.Open(path)){check(document.Source.Size==new Size(240,160)&&document.BackgroundOn&&document.Shapes.Length==1,"background flattened document");using(var loaded=document.Render())using(var expected=canvas.Render())check(Hash(loaded)==Hash(expected),"background roundtrip pixels");}canvas.ApplyBackground(true,new Settings{BgKind=0,BgPreset=3,BgPadding=50,BgAlign=4});using(var image=canvas.Render()){check(image.GetPixel(0,0)!=image.GetPixel(image.Width-1,image.Height-1),"gradient flat");image.Save(Path.Combine(output,"daily-background-gradient.png"));}}
            });
            run("daily background/in-place export retains beauty while dialog preview remains hidden",delegate{using(var overlay=new CaptureOverlay(White(800,600),new Rectangle(0,0,800,600),new Rectangle(70,60,300,210),new[]{new Rectangle(0,0,800,600)})){var canvas=overlay.AnnotationCanvas;canvas.ApplyBackground(true,new Settings{BgKind=1,BgColor=0xE6E6E6,BgPadding=40,BgAlign=4});using(var document=canvas.ExportDocument())using(var rendered=document.Render()){check(document.Source.Size==new Size(300,210)&&document.BackgroundOn&&rendered.Width>300,"capture export dropped beauty");}using(var dialog=new BackgroundDialog(canvas)){dialog.RefreshPreview();using(var image=new Bitmap(dialog.ClientSize.Width,dialog.ClientSize.Height)){using(var g=Graphics.FromImage(image))PreferencesPreview.Draw(g,dialog,dialog);image.Save(Path.Combine(output,"background-dialog-offscreen.png"));}check(!dialog.Visible,"background dialog shown");}}});
        }
        sealed class FakeStartup:IStartupEntry{internal string Value;internal int Removed;public string Read(){return Value;}public void Write(string value){Value=value;}public void Remove(){Removed++;Value=null;}}
        static string Hash(Bitmap image){using(var memory=new MemoryStream()){image.Save(memory,System.Drawing.Imaging.ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(memory.ToArray()));}}
        static Control Find(Control root,string name){foreach(Control child in root.Controls){if(child.AccessibleName==name)return child;var found=Find(child,name);if(found!=null)return found;}return null;}
    }
}
